<?php
/**
 * Evaluate batches of function-level cases against the real legacy code.
 *
 *   php legacy-harness/bin/run-functions.php <cases.json> <true|false>
 *
 * The second argument is DISPLAY_PRICE_WITH_TAX. It is a constant, so each mode
 * needs its own process. Cases are generated by scripts/golden/generate.mjs.
 *
 * Only two entries are not direct calls into legacy functions:
 *   inclusive_tax: the tax-inclusive back-out expression that order::cart()
 *                  writes inline (classes/order.php:318), copied verbatim
 *   php_*:         PHP built-ins (string casts, number_format) that the
 *                  legacy code relies on; they pin down the JS helpers in
 *                  api/src/domain/phpNumber.js
 */

require dirname(__DIR__) . '/lib/bootstrap.php';

harness_run(function () use ($argv) {
    $cases = json_decode(file_get_contents($argv[1]), true);
    $catalog = harness_load_catalog();
    harness_boot($catalog, array('displayPriceWithTax' => $argv[2] === 'true'));

    global $currencies;
    $out = array();

    foreach ($cases as $group => $list) {
        $results = array();
        foreach ($list as $args) {
            switch ($group) {
                case 'tep_round':
                    $r = harness_num(tep_round($args[0], $args[1]));
                    break;
                case 'tax_rate':
                    $r = harness_num(tep_get_tax_rate($args[0], $args[1], $args[2]));
                    break;
                case 'tax_description':
                    $r = tep_get_tax_description($args[0], $args[1], $args[2]);
                    break;
                case 'add_tax':
                    $r = harness_num(tep_add_tax($args[0], $args[1]));
                    break;
                case 'calculate_tax':
                    $r = harness_num(tep_calculate_tax($args[0], $args[1]));
                    break;
                case 'inclusive_tax':
                    $shown_price = $args[0];
                    $products_tax = $args[1];
                    // verbatim from classes/order.php line 318
                    $r = harness_num($shown_price - ($shown_price / (($products_tax < 10) ? "1.0" . str_replace('.', '', $products_tax) : "1." . str_replace('.', '', $products_tax))));
                    break;
                case 'calculate_price':
                    $GLOBALS['currency'] = $args[3];
                    $r = harness_num($currencies->calculate_price($args[0], $args[1], $args[2]));
                    break;
                case 'format':
                    // args: number, currency code, calculate_currency_value, currency_value
                    $r = $currencies->format($args[0], $args[2], $args[1], $args[3]);
                    break;
                case 'cart_calculate':
                    // args: currency code, items [{productId, qty, attributes:[{optionId, valueId}]}]
                    $GLOBALS['currency'] = $args[0];
                    $cart = new shoppingCart();
                    foreach ($args[1] as $item) {
                        $attributes = array();
                        foreach ($item['attributes'] as $a) $attributes[(int)$a['optionId']] = (int)$a['valueId'];
                        $uprid = tep_get_uprid($item['productId'], $attributes);
                        $cart->contents[$uprid] = array('qty' => (int)$item['qty']);
                        if ($attributes) $cart->contents[$uprid]['attributes'] = $attributes;
                    }
                    $r = array('total' => harness_num($cart->show_total()), 'weight' => harness_num($cart->show_weight()), 'count' => (int)$cart->count_contents());
                    break;
                case 'php_float_to_string':
                    $r = (string)(float)$args[0];
                    break;
                case 'php_to_number':
                    // PHP's numeric coercion of a string, as used by arithmetic
                    $r = harness_num($args[0] + 0);
                    break;
                case 'php_number_format':
                    $r = number_format($args[0], $args[1], $args[2], $args[3]);
                    break;
                default:
                    throw new RuntimeException("Unknown case group $group");
            }
            $results[] = array('args' => $args, 'expected' => $r);
        }
        $out[$group] = $results;
    }

    return $out;
});
